use vstd::prelude::*;

verus! {
    spec fn score(P: i8, T: i8) -> i8
        requires
            250 <= P <= 3500,
            P % 250 == 0,
            0 <= T <= 180,
    {
        max(3 * P / 10, P - P * T / 250)
    }

    fn determine_winner(a: i8, b: i8, c: i8, d: i8) -> (result: String)
        requires
            250 <= a <= 3500,
            a % 250 == 0,
            0 <= c <= 180,
            250 <= b <= 3500,
            b % 250 == 0,
            0 <= d <= 180,
        ensures
            result == "Misha" ==> score(a, c) > score(b, d),
            result == "Vasya" ==> score(b, d) > score(a, c),
            result == "Tie" ==> score(a, c) == score(b, d),
    {
        let score_a = score(a, c);
        let score_b = score(b, d);

        if score_a > score_b {
            return "Misha".to_string();
        } else if score_b > score_a {
            return "Vasya".to_string();
        } else {
            return "Tie".to_string();
        }
    }
}
